  function castAbility(ability, pokemon, board, target2, canCrit = true, preventDefaultAnim = false) {
    if (pokemon.canCast === false) return;
    let crit = false;
    const abilityStrategy = AbilityStrategies[ability];
    if (canCrit && (pokemon.effects.has("ABILITY_CRIT" /* ABILITY_CRIT */) || abilityStrategy.canCritByDefault)) {
      crit = chance(pokemon.critChance / 100, pokemon);
    }
    abilityStrategy.process(pokemon, board, target2, crit, preventDefaultAnim);
    pokemon.getEffects(OnAbilityCastEffect).forEach((effect2) => {
      effect2.apply(pokemon, board, target2, crit);
    });
  }

